        var call = receiver.OrElse(e => { alternativeCalls++; return new ValueTask<Result>(Result.Failure(error)); });
        Assert.False(call.IsCompleted);
        source.SetResult(Result.Success());
        var outcome = await call;

        Assert.True(outcome.IsSuccess);
        Assert.Equal(0, alternativeCalls);
    }
}
